// Compute the H2 pair BEFORE mutating either side, so slug pairing is
// driven by the pre-existing (author-authored) heading structure.
const enBodyPreexisting = splitFrontmatter(enCurrent).body
const zhBodyPreexisting = splitFrontmatter(zhCurrent).body
const enRestPre = afterHeader(enBodyPreexisting).rest
const { header: zhHeaderPre, rest: zhRestPre } = afterHeader(zhBodyPreexisting)
const initialPair = extractPairPlan(enRestPre, zhRestPre)

if (hasZh && initialPair.enHeadings.length !== initialPair.zhHeadings.length) {
  throw new Error(
    `gen-package-readme-skeleton: ${enFile} and its ZH sibling have ${initialPair.enHeadings.length} vs ${initialPair.zhHeadings.length} `
    + '## headings; cannot positionally anchor. Fix the pair manually first.',
  )
}

// F1 (UM-FORK-README-SKELETON-RETROFIT): 16 of 65 target packages carry
// an existing ZH `## 概述` that renders the EN `## Overview` (NOT a
// Summary). Left as-is, insertSkeleton's `hasSummary` (`^## 概述$`)
// check matches the Overview and SKIPS inserting the Summary `## 概述`,
// leaving ZH one H2 short of EN. Rename the collision `## 概述` →
// `## Overview` on the ZH body BEFORE staging so a separate Summary
// `## 概述` can coexist, then RE-DERIVE the pair so zhHeadings/slugs
// reflect `## Overview` (slug `overview`, matching EN). The renamed
// Overview then flows into the TOC (not excluded) and receives an
// `<a id="overview">` anchor. The pairing signature compares heading
// DEPTHS only (translation-pairing.ts translationStructureSignature
// pushes node.depth), so the 概述→Overview text rename is
// signature-invisible; only the count asymmetry the bug introduced
// breaks pairing, and F1 fixes that by ensuring both sides insert the
// Summary (6 vs 6 H2s). Idempotent: a retrofitted file carries
// frontmatter, so planRetrofits skips it on the next run; and even if
// frontmatter were stripped, the detector sees `## Overview` (not 概述)
// → empty collision set → no-op.
let zhCurrentRenamed = zhCurrent
let pair = initialPair
if (hasZh && initialPair.overviewCollisionIndices.length > 0) {
  const zhRestRenamed = renameOverviewCollisions(zhRestPre, initialPair.overviewCollisionIndices)
  // Re-stitch the renamed rest behind the unchanged H1 + switcher header
  // and any frontmatter (absent for the 65 targets, kept for generality).
  // body === header + '\n' + rest by afterHeader's own split invariant.
  const zhBodyRenamed = `${zhHeaderPre}\n${zhRestRenamed}`
  zhCurrentRenamed = `${splitFrontmatter(zhCurrent).frontmatter}${zhBodyRenamed}`
  pair = extractPairPlan(enRestPre, zhRestRenamed)
}
